const ids = [];
let checked = 0;
for (let page = 1; page <= 3; page++) {
  const found = await tools.search_products({ query: 'shoe', page });
  checked += found.products.length;
  ids.push(...found.products.filter((product) => product.price < 100).map((product) => product.id));
}
return { ids, checked };
